CREATE OR REPLACE FUNCTION public.enforce_membership_sector_compatibility()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
    current_organization_type TEXT;
    current_membership_roles TEXT[];
BEGIN
    IF TG_OP = 'UPDATE' THEN
        PERFORM lock_membership_sector_keys('organization', OLD.organization_id, NEW.organization_id);
        PERFORM lock_membership_sector_keys('membership', OLD.membership_id, NEW.membership_id);
    ELSE
        PERFORM lock_membership_sector_keys('organization', NEW.organization_id);
        PERFORM lock_membership_sector_keys('membership', NEW.membership_id);
    END IF;

    SELECT o.type, m.roles
      INTO current_organization_type, current_membership_roles
      FROM memberships m
      JOIN organizations o ON o.id = m.organization_id
     WHERE m.id = NEW.membership_id
       AND m.organization_id = NEW.organization_id;

    IF NOT FOUND OR NOT membership_sector_is_compatible(
        current_organization_type,
        current_membership_roles,
        NEW.sector
    ) THEN
        RAISE EXCEPTION 'membership sector is incompatible with organization type or membership roles'
            USING ERRCODE = '23514', CONSTRAINT = 'membership_sector_compatibility';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_membership_sector_set_on_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
    next_organization_type TEXT;
BEGIN
    PERFORM lock_membership_sector_keys('organization', OLD.organization_id, NEW.organization_id);
    PERFORM lock_membership_sector_keys('membership', OLD.id, NEW.id);

    SELECT type INTO next_organization_type
      FROM organizations
     WHERE id = NEW.organization_id;

    IF EXISTS (
        SELECT 1
          FROM membership_sectors ms
         WHERE ms.membership_id = OLD.id
           AND NOT membership_sector_is_compatible(
                next_organization_type,
                NEW.roles,
                ms.sector
           )
    ) THEN
        RAISE EXCEPTION 'membership role change would leave incompatible sector assignments'
            USING ERRCODE = '23514', CONSTRAINT = 'membership_sector_set_compatibility';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_team_invariants_from_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
    IF TG_OP <> 'INSERT' THEN PERFORM check_organization_team_invariants(OLD.organization_id); END IF;
    IF TG_OP <> 'DELETE' AND (TG_OP = 'INSERT' OR NEW.organization_id IS DISTINCT FROM OLD.organization_id) THEN
        PERFORM check_organization_team_invariants(NEW.organization_id);
    ELSIF TG_OP = 'UPDATE' THEN
        PERFORM check_organization_team_invariants(NEW.organization_id);
    END IF;
    RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.refresh_team_state_on_membership_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE old_member INTEGER := 0; old_admin INTEGER := 0; new_member INTEGER := 0; new_admin INTEGER := 0;
BEGIN
    IF TG_OP <> 'INSERT' AND OLD.status = 'active' THEN
        old_member := 1;
        old_admin := CASE WHEN OLD.roles @> ARRAY['admin']::TEXT[] THEN 1 ELSE 0 END;
    END IF;
    IF TG_OP <> 'DELETE' AND NEW.status = 'active' THEN
        new_member := 1;
        new_admin := CASE WHEN NEW.roles @> ARRAY['admin']::TEXT[] THEN 1 ELSE 0 END;
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id THEN
        PERFORM apply_organization_team_delta(NEW.organization_id, new_member - old_member, new_admin - old_admin);
    ELSE
        IF TG_OP <> 'INSERT' THEN PERFORM apply_organization_team_delta(OLD.organization_id, -old_member, -old_admin); END IF;
        IF TG_OP <> 'DELETE' THEN PERFORM apply_organization_team_delta(NEW.organization_id, new_member, new_admin); END IF;
    END IF;
    RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.protect_quote_revision_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'quote_revisions cannot be deleted once created';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF NEW.id <> OLD.id OR NEW.project_id <> OLD.project_id OR NEW.organization_id <> OLD.organization_id THEN
            RAISE EXCEPTION 'quote_revision identity and project ownership are immutable';
        END IF;
        IF NEW.revision_number <> OLD.revision_number THEN
            RAISE EXCEPTION 'quote_revision revision_number is immutable';
        END IF;
        IF NEW.source_type <> OLD.source_type THEN
            RAISE EXCEPTION 'quote_revision source_type is immutable';
        END IF;
        IF NEW.created_at <> OLD.created_at THEN
            RAISE EXCEPTION 'quote_revision created_at is immutable';
        END IF;

        IF NEW.status <> OLD.status THEN
            IF OLD.status = 'draft' AND NEW.status <> 'published' THEN
                RAISE EXCEPTION 'draft quote_revision can only transition to published, not %', NEW.status;
            END IF;
            IF OLD.status = 'superseded' THEN
                RAISE EXCEPTION 'superseded quote_revision cannot transition to %', NEW.status;
            END IF;
            IF OLD.status = 'accepted' AND NEW.status <> 'superseded' THEN
                RAISE EXCEPTION 'accepted quote_revision can only transition to superseded, not %', NEW.status;
            END IF;
            IF OLD.status = 'published' AND NEW.status NOT IN ('accepted', 'superseded') THEN
                RAISE EXCEPTION 'published quote_revision can only transition to accepted or superseded, not %', NEW.status;
            END IF;
        END IF;

        IF OLD.status IN ('published', 'accepted', 'superseded') AND NEW.notes IS DISTINCT FROM OLD.notes THEN
            RAISE EXCEPTION '% quote_revision content cannot be modified', OLD.status;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$
